def load(root,rel):return json.loads((root/rel).read_text())
def put(root,rel,obj):
 p=root/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(obj,indent=2,sort_keys=True)+'\n')
def text(root,rel,s):
 p=root/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def run(root,args):
 result=subprocess.run(args,cwd=root,text=True,capture_output=True)
 if result.returncode:
  raise RuntimeError('Command failed: '+repr(args)+'\n'+result.stdout[-14000:]+'\n'+result.stderr[-14000:])
 return result
def copyrepo(source,destination):
 shutil.copytree(source,destination,ignore=shutil.ignore_patterns('.git','__pycache__','run-output','.pytest_cache'))
 gitdir=run(source,['git','rev-parse','--absolute-git-dir']).stdout.strip()
 (destination/'.git').write_text('gitdir: '+gitdir+'\n')
def guard(root,candidate):
 spec=importlib.util.spec_from_file_location('q046_admission',root/'tests/programs/q046_model_validate.py');module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
 result=module.run_tests(root,candidate=candidate)
 if not result['all_green']:raise RuntimeError(json.dumps(result,indent=2))
 return result
def payload_verify():
 actual=hashlib.sha256(json.dumps(PAYLOAD,sort_keys=True,separators=(',',':')).encode()).hexdigest()
 if actual!=PAYLOAD_SHA256:raise RuntimeError('Installation payload digest mismatch')
 for rel in PAYLOAD:
  p=Path(rel)
  if p.is_absolute() or '..' in p.parts or rel.startswith(('.github/','accepted/','model/','evidence/','versions/','release/')):
   raise RuntimeError('Unsafe staging payload path: '+rel)
def stage(root):
 payload_verify()
 for rel,s in PAYLOAD.items():text(root,rel,s)
 return guard(root,True)

