def public_healthcheck(root):
 # Execute the exact existing public engine's Python heredoc; do not rewrite workflows.
 s=(root/'.github/workflows/00-bubbleverse-model-start-public.yml').read_text().splitlines()
 start=next(i+1 for i,l in enumerate(s) if l.strip()=="python - <<'PY'")
 end=next(i for i in range(start,len(s)) if s[i].strip()=='PY')
 code='\n'.join(l[10:] for l in s[start:end])+'\n'
 env=dict(os.environ,BV_OPERATION='test',BV_INPUT='')
 result=subprocess.run([sys.executable,'-c',code],cwd=root,env=env,text=True,capture_output=True)
 output=load(root,'run-output/result.json') if (root/'run-output/result.json').is_file() else {}
 if result.returncode or output.get('all_green') is not True:raise RuntimeError('Public healthcheck failed\n'+result.stdout[-5000:]+'\n'+result.stderr[-5000:]+'\n'+json.dumps(output)[-15000:])
 return output

