 before={p.relative_to(root).as_posix():digest(p) for name in ['accepted','model','versions','release','candidate','evidence'] for p in (root/name).rglob('*') if p.is_file()}
 public=public_healthcheck(root)
 after={p.relative_to(root).as_posix():digest(p) for name in ['accepted','model','versions','release','candidate','evidence'] for p in (root/name).rglob('*') if p.is_file()}
 if before!=after:raise RuntimeError('The test healthcheck mutated scientific state')
 suite=run(root,[sys.executable,'-m','unittest','discover','-s','tests/programs','-p','test_*.py'])
 return {'q046':q,'formal_stdout':formal.stdout,'campaign_stdout':campaign.stdout,'public_healthcheck':public,'public_healthcheck_scientific_mutation':False,'unittest_stdout':suite.stdout,'unittest_stderr':suite.stderr}

